(function (global) {
  'use strict';
  const ca = (value, digits = 1) => value == null ? 'dada no disponible' : Number(value).toFixed(digits).replace('.', ',');
  const date = value => {
    if (!value) return 'data no disponible';
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? String(value) : parsed.toLocaleString('ca-ES', { timeZone:'Europe/Madrid', day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' });
  };
  const commonLimits = 'La lectura identifica patrons i sectors candidats, però no demostra per si sola causalitat, estat ecològic complet ni efectes sobre espècies concretes. Cal interpretar-la amb la resolució, la data i les limitacions de la font i validar al camp les decisions que puguin alterar hàbitats o processos.';
  const commonManagement = 'Prioritzar la comprovació dels sectors que destaquen, contrastar-los amb hàbitats, biodiversitat, aigua, accessibilitat i usos, definir un objectiu ecològic explícit i aplicar seguiment abans i després de qualsevol actuació. No es justifica una intervenció generalitzada només a partir d’aquesta capa.';

  function buildFactory(D, modeGuides, layerGuides) {
    const sat = D.metrics.satellite || {};
    const readings = D.dailyReadings?.readings || {};
    const analytics = D.dailyHistory?.analytics || {};
    const sentinelDate = sat.sentinelDate || readings.ndvi?.data_at_utc;
    const structural = {
      base:{sources:['ICGC · model d’elevacions de 5 m','OpenStreetMap · carreteres, camins i nuclis'],date:'cartografia estructural; consulta indicada a les fonts del visor',facts:[['Altitud','607–2.379 m'],['Xarxa dins l’àmbit',`${ca(D.metrics.pathsKm)} km`],['Carreteres classificades',`${ca(D.metrics.roadsKm)} km`]],what:'El mapa base representa el relleu, l’altitud relativa, la xarxa viària i els nuclis que permeten situar totes les lectures EcoRadar.',context:'A Alinyà, el fort gradient altitudinal i el relleu condicionen insolació, temperatura, circulació de l’aigua, accessibilitat i continuïtat d’hàbitats. Les carreteres i poblacions són context, no una mesura de pressió.',relationships:'El relleu ajuda a interpretar temperatura superficial, humitat, refugis climàtics, pendent, orientació, connectivitat i propagació potencial del foc. La xarxa viària informa accessibilitat potencial, no freqüentació.',changes:'El relleu és estructural i no té una evolució diària interpretable. Canvis a la xarxa viària o als usos podrien modificar accessibilitat, fragmentació i pressions, però aquesta capa no els quantifica.',consequences:'Una interpretació incorrecta del context topogràfic pot ocultar fondals, solanes, divisòries i colls amb funcions ecològiques diferents; no implica per si sola un impacte sobre fauna o vegetació.'},
      habitats:{sources:['Generalitat de Catalunya · cartografia d’hàbitats d’interès comunitari'],date:'cartografia oficial disponible al projecte',facts:[['HIC cartografiats',`${ca(D.metrics.hicHa,2)} ha`],['HIC prioritaris',`${ca(D.metrics.hicPriorHa,2)} ha`]],what:'La lectura delimita hàbitats d’interès comunitari (HIC) i els que la normativa classifica com a prioritaris.',context:'A la Muntanya d’Alinyà aquests hàbitats actuen com a filtre de compatibilitat: concentren valors i requeriments ecològics que cal comprovar abans de modificar vegetació, accessos o règims de pertorbació.',relationships:'S’ha de creuar amb biodiversitat, cobertura, vigor, humitat, aigua, connectivitat, ús públic i foc. La coincidència espacial orienta validació, però no prova l’estat de conservació ni la presència actual d’una espècie.',changes:'Una reducció o fragmentació real de l’hàbitat pot debilitar connectivitat i disponibilitat de recursos. Un augment cartogràfic pot derivar d’una actualització de la font i no d’una recuperació ecològica.',consequences:'La degradació funcional pot afectar estructura vegetal, microclima, recursos tròfics, refugis i moviments de fauna. L’abast depèn del tipus d’hàbitat i s’ha de validar.'},
      biodiversity:{sources:['GBIF · registres públics','iNaturalist · observacions públiques'],date:'data de descàrrega indicada a la metodologia del visor',facts:[['Registres',String(D.metrics.records)],['Espècies citades',String(D.metrics.species)],['Ratpenats públics',`${D.metrics.biodiversityGroups?.records?.Ratpenats || 0} registres`]],what:'La lectura mostra observacions públiques georeferenciades i els tàxons citats, és a dir, coneixement disponible i no un cens exhaustiu.',context:'Els 731 registres i 516 espècies citades confirmen una base de coneixement rellevant, però la distribució també reflecteix on s’ha mostrejat i publicat. Els buits no són absències; zero registres públics de ratpenats és un buit de dades.',relationships:'Els punts s’han de contrastar amb hàbitats, aigua, refugis climàtics, mosaic, accessos i ús públic. La coincidència pot orientar prospecció o precaució, però no estima abundància, ocupació ni qualitat d’hàbitat.',changes:'Un augment de registres pot significar més esforç d’observació i no més biodiversitat. Una disminució tampoc prova declivi sense un mostreig comparable en temps, espai i mètode.',consequences:'Decidir només amb dades oportunistes pot invisibilitzar fauna nocturna, espècies discretes o sectors poc visitats i provocar una priorització esbiaixada.'},
      vegetation:{sources:['Copernicus Land Monitoring Service · HRL 2023'],date:'2023',facts:[['Cobertura vegetal',`${ca(sat.vegetationCoverPct)} %`],['Superfície vegetada',`${ca(sat.vegetationCoverHa)} ha`]],what:'La lectura identifica presència de cobertura arbòria o herbàcia a partir dels productes d’alta resolució de Copernicus.',context:'La proporció vegetada descriu l’estructura general d’Alinyà, però no separa per si sola comunitats, estat, humitat, vigor ni càrrega de combustible.',relationships:'La cobertura condiciona temperatura superficial, intercepció de pluja, erosió, connectivitat i hàbitat. Cal separar-la de l’NDVI, l’NDMI i el tipus de coberta ICGC, que responen preguntes diferents.',changes:'Una pèrdua sostinguda pot augmentar sòl exposat, escorrentia i fragmentació; un augment pot afavorir continuïtat ecològica però també homogeneïtzació del mosaic o continuïtat de combustible segons estructura i context.',consequences:'Canvis extensos poden alterar microclima, sòl, cicle de l’aigua, disponibilitat d’espais oberts i forestals i moviments de fauna; la direcció ecològica no és automàticament positiva o negativa.'},
      temperature:{sources:['Landsat 8/9 · temperatura superficial QA-vàlida'],date:sat.temperatureDateRange || 'estius 2025–2026',facts:[['Mediana',`${ca(sat.temperature?.median)} °C`],['Percentil 10',`${ca(sat.temperature?.p10)} °C`],['Percentil 90',`${ca(sat.temperature?.p90)} °C`],['Cobertura',`${ca(sat.temperatureCoveragePct)} %`]],what:'Mesura la temperatura de la superfície terrestre observada pel satèl·lit, no la temperatura de l’aire.',context:'La diferència entre sectors més frescos i més calents d’Alinyà sintetitza l’efecte combinat d’altitud, orientació, coberta, humitat i substrat durant les observacions diürnes d’estiu.',relationships:'S’ha d’interpretar amb NDMI, NDVI, albedo, cobertura, aigua i refugis climàtics. Pot aportar context al perill d’incendi, però una composició estival no substitueix la meteorologia d’avui.',changes:'Un augment persistent en observacions comparables pot indicar més escalfament superficial o menys capacitat de refredament; una disminució pot associar-se a més ombra, humitat o coberta, però també a diferències de data, atmosfera o sensor.',consequences:'L’escalfament sostingut pot intensificar evaporació, estrès hídric i pèrdua de qualitat microclimàtica, amb possibles efectes sobre vegetació, fauna i permanència dels refugis.'},
      vigor:{sources:['Copernicus Sentinel-2 · NDVI'],date:date(sentinelDate),facts:[['Mediana NDVI',ca(sat.ndvi?.median,3)],['Percentil 10',ca(sat.ndvi?.p10,3)],['Percentil 90',ca(sat.ndvi?.p90,3)]],what:'L’NDVI és un índex espectral de vigor o activitat fotosintètica relativa, calculat amb la resposta de la vegetació al roig i a l’infraroig proper.',context:'La distribució d’Alinyà diferencia cobertes poc vegetades o amb resposta baixa de sectors amb resposta fotosintètica alta en la data de captura. No diagnostica salut individual ni qualitat ecològica.',relationships:'Cal creuar-lo amb NDMI, temperatura, cobertura, albedo, hàbitats i refugis. Un NDVI alt pot correspondre a vegetació densa, però no informa directament d’humitat, diversitat, estructura o combustible.',changes:'Una disminució en escenes comparables pot indicar senescència, sequera, pertorbació o canvi de coberta; un augment pot indicar creixement o recuperació. L’estacionalitat obliga a comparar dates i condicions equivalents.',consequences:'Una baixada sostinguda pot reduir productivitat, ombra i recursos per a fauna i, si coincideix amb sequedat, augmentar vulnerabilitat; la causa no es pot assignar només amb NDVI.'},
      moisture:{sources:['Copernicus Sentinel-2 · NDMI'],date:date(sentinelDate),facts:[['Mediana NDMI',ca(sat.ndmi?.median,3)],['Percentil 10',ca(sat.ndmi?.p10,3)],['Percentil 90',ca(sat.ndmi?.p90,3)]],what:'L’NDMI és un índex espectral de la humitat relativa de la coberta vegetal basat en l’infraroig proper i l’infraroig d’ona curta.',context:'A Alinyà separa sectors vegetalment més secs i més humits en la data de l’escena. És una lectura relativa: no expressa percentatge d’aigua, humitat del sòl ni humitat fina del combustible.',relationships:'Es complementa amb NDVI, temperatura superficial, precipitació, ForestDrought, cobertura, aigua i perill d’incendi. Una coincidència de NDMI baix i temperatura alta mereix validació prioritària.',changes:'Una disminució comparable pot ser compatible amb dessecació de la vegetació; un augment, amb recuperació d’humitat. Pluja recent, fenologia, ombres i tipus de coberta poden modificar la resposta.',consequences:'La pèrdua sostinguda d’humitat pot afectar funcionament vegetal, microclima, disponibilitat d’aigua biològica i inflamabilitat, amb efectes indirectes sobre fauna i hàbitats.'},
      albedo:{sources:['Copernicus Sentinel-2 · estimació d’albedo de banda ampla'],date:date(sentinelDate),facts:[['Mediana',ca(sat.albedo?.median,3)],['Percentil 10',ca(sat.albedo?.p10,3)],['Percentil 90',ca(sat.albedo?.p90,3)]],what:'L’albedo és la fracció de radiació solar que una superfície reflecteix. Depèn del color i estat del sòl, la vegetació, la humitat, la rugositat, l’orientació i, quan n’hi ha, la neu.',context:'A Alinyà, la mediana i el rang central descriuen un mosaic de superfícies amb capacitats de reflexió diferents. Un valor baix no és necessàriament dolent: pot correspondre a vegetació densa; un valor alt pot correspondre a roca, sòl clar o neu.',relationships:'S’ha d’interpretar amb temperatura superficial, NDVI, NDMI, cobertura, altitud i orientació. Una superfície que reflecteix menys pot absorbir més radiació, però el resultat tèrmic també depèn d’humitat, evapotranspiració i rugositat.',changes:'Si disminueix mantenint constants la resta de factors, pot augmentar l’energia absorbida i contribuir a més escalfament superficial; si augmenta, pot reduir-la. Canvis de vegetació, humitat, sòl nu o neu poden invertir la interpretació ecològica.',consequences:'Una evolució cap a més absorció, si coincideix amb pèrdua d’humitat o cobertura, pot intensificar temperatura i estrès hídric i afectar hàbitats, fauna i perill d’incendi. L’albedo sol no permet establir aquesta cadena causal.'},
      climateRefuges:{sources:['Landsat 8/9 · temperatura superficial','Copernicus Sentinel-2 · NDVI i NDMI','Cartografia hídrica disponible al projecte'],date:`LST ${sat.temperatureDateRange || 'estius 2025–2026'}; Sentinel-2 ${date(sentinelDate)}`,facts:[['Potencial alt o molt alt',`${ca(D.metrics.climateRefugesHighPct)} %`]],what:'És un cribratge espacial que combina frescor superficial, humitat vegetal, vigor i context hídric per localitzar possibles refugis climàtics.',context:'Els sectors destacats d’Alinyà són candidats on coincideixen condicions potencialment favorables durant calor o sequera; no són refugis certificats ni garanteixen persistència futura.',relationships:'Integra temperatura, NDMI, NDVI i aigua i s’ha de contrastar amb hàbitats, biodiversitat, connectivitat, orientació i permanència hídrica.',changes:'La contracció reiterada dels sectors destacats podria indicar pèrdua de frescor o humitat; l’expansió podria ser favorable, però només és comparable amb la mateixa metodologia, estació i qualitat de dades.',consequences:'La pèrdua de refugis pot reduir opcions microclimàtiques per a fauna i vegetació i debilitar connectivitat funcional durant episodis extrems.'},
      fires:{sources:['Generalitat de Catalunya · WFS VEGETACIO:VEGETACIO_INCENDIS'],date:'perímetres consolidats de 2000 i 2012',facts:[['Perímetres','2'],['Superfície cremada',`${ca(D.metrics.burnedHa)} ha`],['Àmbit afectat',`${ca(D.metrics.burnedPct)} %`]],what:'La lectura mostra els perímetres oficials d’incendis històrics consolidats dins l’àmbit.',context:'Els focs de 2000 i 2012 localitzen antecedents de pertorbació i permeten analitzar recuperació i coincidència amb relleu, coberta i accessos. No indiquen el perill d’avui.',relationships:'Cal creuar-los amb cobertura, vigor, humitat, hàbitats, biodiversitat, erosió, accessibilitat i perill estructural o actual.',changes:'La capa només canvia quan la font oficial incorpora un nou perímetre consolidat. No és una sèrie operativa diària ni un detector d’incendis actius.',consequences:'Els efectes depenen de severitat, recurrència i resposta postincendi: poden modificar sòl, aigua, estructura, mosaic, hàbitats i trajectòries de successió.'},
      management:{sources:['Síntesi EcoRadar de capes verificades; sense assignació territorial automàtica'],date:'segons la data de cada capa superposada',facts:[['Funció','cribratge previ'],['Ordre d’actuació','no assignat']],what:'El cribratge de gestió superposa restriccions i elements de context per indicar on cal validar millor abans de decidir, no on s’ha d’actuar.',context:'A Alinyà, els HIC, accessos, punts d’ús públic i incendis històrics obliguen a formular preguntes diferents sobre compatibilitat, pressió real, antecedents i viabilitat operativa.',relationships:'La decisió ha d’incorporar totes les lectures pertinents: hàbitats, biodiversitat, aigua, connectivitat, mosaic, vigor, humitat, temperatura, foc i ús públic.',changes:'No és un indicador temporal. La seva interpretació canvia quan s’actualitzen les capes de base o la validació de camp, no cada dia.',consequences:'Confondre el cribratge amb una prescripció pot provocar actuacions en valors sensibles o ometre sectors degradats; la priorització requereix objectiu, evidència i seguiment.'}
    };
    const layerSpecific = {
      access:{sources:['OpenStreetMap · carreteres, camins i pistes'],date:'consulta indicada a la metodologia del visor',facts:[['Xarxa dins l’àmbit',`${ca(D.metrics.pathsKm)} km`],['Carreteres classificades',`${ca(D.metrics.roadsKm)} km`]],what:'La capa representa la xarxa viària cartografiada i, per tant, accessibilitat territorial potencial.',context:'Els 124,8 km quantificats corresponen només als trams dins l’àmbit d’Alinyà; les línies externes són context. La capa no mesura persones, vehicles, freqüentació ni pressió real.',relationships:'Permet prioritzar la validació de possibles conflictes amb hàbitats, fauna, punts d’aigua, erosió, ús públic i gestió preventiva del foc.',changes:'Els canvis només reflecteixen actualitzacions d’OSM o de la xarxa, no una evolució diària de la pressió.',consequences:'Una accessibilitat elevada pot facilitar gestió i emergències, però també fragmentació o molèsties si existeix ús real; aquesta capa no permet afirmar que aquests impactes es produeixin.'},
      publicUse:{sources:['OpenStreetMap · elements d’ús públic'],date:'consulta indicada a la metodologia del visor',facts:[['Punts cartografiats',String(D.metrics.publicPoints)]],what:'La capa situa elements d’ús públic publicats a OSM.',context:'Els 18 punts són una mostra d’elements cartografiats a Alinyà i serveixen per orientar comprovacions, no per estimar visitants o intensitat d’ús.',relationships:'S’ha de contrastar amb accessos, hàbitats, biodiversitat sensible, aigua i refugis climàtics per detectar possibles conflictes que després cal validar.',changes:'Un augment de punts pot reflectir millor cartografia i no necessàriament més ús. No hi ha una sèrie de freqüentació comparable.',consequences:'Sense dades d’ús real no es poden atribuir molèsties, erosió o impactes sobre fauna; sí que es poden prioritzar els llocs on mesurar-los.'},
      places:{sources:['OpenStreetMap · topònims i nuclis'],date:'consulta indicada a la metodologia del visor',facts:[['Nuclis mostrats',String(D.metrics.settlements)]],what:'La capa situa topònims classificats com a nuclis habitats dins la finestra cartogràfica.',context:'Els punts permeten orientar les lectures respecte dels nuclis d’Alinyà, però no delimiten la taca urbana ni estimen població o exposició.',relationships:'És context per a accessibilitat, ús públic, serveis, emergències i gestió, sense convertir-se en un indicador ecològic de pressió.',changes:'Només varia quan canvia la font cartogràfica; no representa dinàmica demogràfica.',consequences:'No permet inferir impactes ecològics dels nuclis sense dades d’activitat, infraestructures, fluxos o pressions.'},
      landcover:{sources:['ICGC · mapa de cobertes del sòl 2024'],date:'2024',facts:[['Bosc',`${ca(D.metrics.forestPct)} %`],['Prats i herbassars',`${ca(D.metrics.grasslandPct)} %`]],what:'La capa classifica el tipus de cobertura física del sòl: bosc, matollar, herbassars, conreus, aigua, roca, vies i nuclis.',context:'A Alinyà descriu el mosaic territorial i ajuda a separar cobertes amb funcions ecològiques diferents. No mesura vigor, humitat, qualitat d’hàbitat ni combustible.',relationships:'Cal combinar-la amb NDVI, NDMI, temperatura, hàbitats, connectivitat i foc per interpretar estructura i funcionament.',changes:'Una comparació futura pot detectar transicions de coberta només si conserva classificació i resolució compatibles.',consequences:'L’homogeneïtzació o pèrdua de cobertes pot afectar mosaic, erosió, recursos i connectivitat, però la direcció depèn de quines cobertes canvien i on.'}
    };

    function fireProfile() {
      const f=D.currentFire, w=f.weather || {}, trend=analytics.current_fire_danger?.trend || {};
      return {sources:['Meteocat/XEMA · meteorologia i acumulacions','CREAF ForestDrought · potencial de foc forestal','Generalitat de Catalunya · perill estructural 2024','Sentinel-2/Landsat · variables dinàmiques amb control de frescor','Agents Rurals · Pla Alfa, mostrat només com a context oficial'],date:date(f.checkedAtUtc),facts:[['Índex mitjà',`${ca(f.summary?.mean_index_0_100)}/100`],['Categoria',f.summary?.predominant_category || 'no disponible'],['Màxim territorial',`${ca(f.summary?.max_index_0_100)}/100`],['Pla Alfa',w.pla_alfa_label || f.plaAlfa?.label || 'dada no disponible']],what:'L’índex EcoRadar 0–100 integra vulnerabilitat estructural, estat de vegetació o sequera i meteorologia recent. El Pla Alfa és context oficial separat i no entra numèricament al càlcul.',context:`La comprovació del ${date(f.checkedAtUtc)} dona una mitjana de ${ca(f.summary?.mean_index_0_100)}/100 i categoria ${f.summary?.predominant_category || 'no disponible'}. La variació espacial reflecteix factors territorials, mentre la meteorologia observada s’aplica amb la resolució real de l’estació, no com si cada cel·la tingués una observació pròpia.`,relationships:'Relaciona ForestDrought, NDMI, temperatura superficial, continuïtat vegetal, pendent, orientació, humitat, vent i ratxes. Temperatura de l’aire i precipitació expliquen el context; Pla Alfa informa l’operativa oficial.',changes:'Un augment pot provenir de més vent o ratxa, humitat més baixa, vegetació o superfície més seca, o major pes dels factors estructurals disponibles. Una disminució pot reflectir millora meteorològica o d’humitat, però no elimina la vulnerabilitat estructural.',consequences:'Un empitjorament sostingut pot reduir el marge operatiu i augmentar la necessitat de vigilància, restriccions i comprovació de combustible. L’índex no prediu ignicions ni severitat ecològica.',temporal:trend.label ? `${trend.symbol || '→'} ${trend.label}; variació ${ca(trend.variation_pct)} % respecte de l’actualització comparable anterior.` : 'No hi ha una comparació temporal homogènia disponible.'};
    }
    function structuralFire() { return {sources:['Generalitat de Catalunya · perill estructural 2024','Landsat 8/9 · temperatura superficial','Sentinel-2 · NDMI','ICGC/OSM · cobertes, relleu, accessos i incendis'],date:'components estructurals i compostos amb dates indicades al visor',facts:[['Alt o molt alt',`${ca(D.metrics.fireIntegratedHighPct)} %`],['Índex mitjà',ca(D.metrics.fireIntegratedMean,2)]],what:'És un índex territorial integrat de perill estructural, temperatura superficial, sequedat espectral, coberta i concurrència territorial.',context:'Localitza els sectors d’Alinyà on coincideixen factors que poden afavorir el comportament del foc. No descriu la meteorologia del dia ni la probabilitat d’ignició.',relationships:'Connecta coberta, NDMI, temperatura, relleu, accessibilitat i antecedents d’incendi. S’ha de llegir amb el perill d’avui, Pla Alfa, hàbitats, biodiversitat i objectius de mosaic.',changes:'Les variacions només són interpretables quan s’actualitza un component amb una observació comparable. No s’ha de presentar com a canvi diari.',consequences:'Sectors estructuralment elevats poden requerir més validació de combustible, continuïtat i compatibilitat ecològica, però no justifiquen desbrossament generalitzat.'}; }

    const optional = {fireCurrent:fireProfile,fireDanger:structuralFire};
    return function build(selection) {
      const key=selection.key, guide=selection.guide || {}, aliases={hic:'habitats',biodiversity:'biodiversity',fires:'fires'};
      const base=selection.type === 'layer' ? (layerSpecific[key] || structural[aliases[key]]) || {} : (optional[key] ? optional[key]() : structural[key]) || {};
      const profile={
        name:guide.title || guide.label || key,
        generatedAt:new Date().toLocaleString('ca-ES',{timeZone:'Europe/Madrid'}),
        dataDate:base.date || 'segons la font indicada al visor', sources:base.sources || ['Font indicada a la lectura activa del visor'],
        facts:(base.facts || []).map(([label,value,note])=>({label,value,note})),
        what:base.what || guide.copy || 'Lectura cartogràfica disponible a EcoRadar.',
        contribution:guide.reading || 'Aporta una lectura territorial que s’ha de combinar amb la resta d’evidències disponibles.',
        context:base.context || `${guide.copy || ''} ${guide.reading || ''}`,
        territorial:`El mapa reproduït correspon exactament a la lectura activa. Els colors i símbols s’interpreten segons la llegenda del visor: ${(guide.legend || []).map(row=>row[1]).join('; ')}. No s’atribueixen valors fora de la cobertura real de la font.`,
        relationships:base.relationships || 'S’ha de contrastar amb hàbitats, biodiversitat, aigua, cobertura, estat de la vegetació, relleu, accessibilitat i foc quan siguin pertinents.',
        changes:base.changes || 'No hi ha una sèrie temporal homogènia que permeti atribuir un augment o una disminució; qualsevol comparació futura ha de conservar font, resolució, estació i mètode.',
        consequences:base.consequences || 'Els efectes ecològics depenen del procés representat i no es poden atribuir a una sola capa sense evidència complementària.',
        improve:base.improve || commonManagement,
        conclusions:base.conclusions || ['Utilitzar la lectura com a evidència de cribratge, no com una ordre automàtica d’actuació.','Prioritzar els sectors que destaquen per al contrast amb la resta d’indicadors i la validació de camp.','Conservar la traçabilitat de font, data, resolució i incertesa abans de decidir.'],
        limits:[guide.limit || commonLimits, commonLimits], temporal:base.temporal || 'No hi ha una comparació temporal homogènia disponible per a aquesta lectura.'
      };
      return profile;
    };
  }
  global.EcoRadarAlinyaReportProfiles = { buildFactory };
})(window);
